+  // Whether the machine can perform a 16-byte atomic load/store that has comparable performance to
+  // doing 2 separate jlong loads/stores. For example, on x86, fast 16-byte atomic load/store is
+  // implemented using vmovdqa.
+  static bool supports_fast_16byte_atomic_access() {
+#ifdef LINUX
+    // Intel guarantees atomicity of 16-byte vmovdqa, AMD does not
+    if (!is_intel() || !supports_avx()) {
+      return false;
+    }
+#ifdef COMPILER2
+    if (MaxVectorSize < 16) {
+      return false;
+    }
+#endif // COMPILER2
+    return true;
+
+#else // LINUX
+    return false;
+#endif // LINUX
+  }
+

@@ -18322,0 +18322,32 @@
+instruct loadVAtomic(vec dst, memory mem)
+%{
+  match(Set dst (LoadVectorAtomic mem));
+
+  ins_cost(125);
+  format %{ "vmovdqa $dst, $mem" %}
+
+  ins_encode %{
+    int vlen_in_bytes = Matcher::vector_length_in_bytes(this);
+    assert(vlen_in_bytes == 16, "unexpected vector atomic load with length %d", vlen_in_bytes);
+    assert(VM_Version::supports_fast_16byte_atomic_access(), "not supported");
+    __ movdqa($dst$$XMMRegister, $mem$$Address);
+  %}
+
+  ins_pipe(ialu_reg_mem);
+%}
+
+instruct storeVAtomic(memory mem, vec src)
+%{
+  match(Set mem (StoreVectorAtomic mem src));
+
+  ins_cost(125);
+  format %{ "vmovdqa $mem, $src" %}
+  ins_encode %{
+    int vlen_in_bytes = Matcher::vector_length_in_bytes(this, $src);
+    assert(vlen_in_bytes == 16, "unexpected vector atomic load with length %d", vlen_in_bytes);
+    assert(VM_Version::supports_fast_16byte_atomic_access(), "not supported");
+    __ movdqa($mem$$Address, $src$$XMMRegister);
+  %}
+  ins_pipe(ialu_mem_reg);
+%}
+

